mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Pay_Clause as conPayClause, fp.Fp_Date as fpDate, fp.Create_Uname as createUname, fp.Fp_Code as fpCode, c1.C_Name as fpdPayeeName, mn.* from Fund_Plan_Dtl mn
left join Con_Contract con on mn.Con_Id = con.Con_Id left join Fund_Plan fp on fp.id = mn.Fp_Id left join Sys_Company c1 on c1.C_Name=mn.Fpd_Payee_Id where mn.Con_Id = #{params.conId}
and mn.P_Id=#{params.pId}
and fp.Te_Id = #{params.teId}
and fp.State = 7 order by fp.Create_Time desc, mn.Fpd_Sort asc
